create extension if not exists pgcrypto;

create table if not exists companies (id uuid primary key default gen_random_uuid(), name text not null, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists company_users (id uuid primary key default gen_random_uuid(), company_id uuid not null references companies(id) on delete cascade, user_id uuid not null, role text not null default 'vendedor', active boolean not null default true, created_at timestamptz not null default now(), unique(company_id, user_id));
create table if not exists customers (id uuid primary key default gen_random_uuid(), company_id uuid not null references companies(id) on delete cascade, name text not null, document text, email text, phone text, total_purchased numeric(14,2) not null default 0, sale_count integer not null default 0, avg_ticket numeric(14,2) not null default 0, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists products (id uuid primary key default gen_random_uuid(), company_id uuid not null references companies(id) on delete cascade, name text not null, sku text, cost numeric(14,2) not null default 0, price numeric(14,2) not null default 0, stock numeric(14,3) not null default 0, minimum_stock numeric(14,3) not null default 0, active boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(company_id, sku));
create table if not exists sales (id uuid primary key default gen_random_uuid(), company_id uuid not null references companies(id) on delete cascade, customer_id uuid references customers(id), status text not null default 'pending', items jsonb not null default '[]', subtotal numeric(14,2) not null default 0, discount numeric(14,2) not null default 0, addition numeric(14,2) not null default 0, total numeric(14,2) not null default 0, cost_total numeric(14,2) not null default 0, profit numeric(14,2) not null default 0, idempotency_key text, sale_date date not null default current_date, created_at timestamptz not null default now(), unique(company_id, idempotency_key));
create table if not exists sale_items (id uuid primary key default gen_random_uuid(), company_id uuid not null references companies(id) on delete cascade, sale_id uuid not null references sales(id) on delete cascade, product_id uuid not null references products(id), quantity numeric(14,3) not null, price numeric(14,2) not null, cost numeric(14,2) not null default 0);
create table if not exists stock_movements (id uuid primary key default gen_random_uuid(), company_id uuid not null references companies(id) on delete cascade, product_id uuid not null references products(id), sale_id uuid references sales(id), purchase_id uuid, type text not null, quantity numeric(14,3) not null, reason text, created_at timestamptz not null default now());
create table if not exists financial_entries (id uuid primary key default gen_random_uuid(), company_id uuid not null references companies(id) on delete cascade, sale_id uuid references sales(id), purchase_id uuid, type text not null, status text not null default 'pending', description text, amount numeric(14,2) not null, due_date date not null, paid_date date, created_at timestamptz not null default now());
create table if not exists suppliers (id uuid primary key default gen_random_uuid(), company_id uuid not null references companies(id) on delete cascade, name text not null, document text, email text, phone text, created_at timestamptz not null default now());
create table if not exists purchases (id uuid primary key default gen_random_uuid(), company_id uuid not null references companies(id) on delete cascade, supplier_id uuid references suppliers(id), status text not null default 'draft', total numeric(14,2) not null default 0, expected_date date, created_at timestamptz not null default now());
create table if not exists purchase_items (id uuid primary key default gen_random_uuid(), company_id uuid not null references companies(id) on delete cascade, purchase_id uuid not null references purchases(id) on delete cascade, product_id uuid not null references products(id), quantity numeric(14,3) not null, cost numeric(14,2) not null);
create table if not exists quotes (id uuid primary key default gen_random_uuid(), company_id uuid not null references companies(id) on delete cascade, customer_id uuid references customers(id), status text not null default 'draft', items jsonb not null default '[]', total numeric(14,2) not null default 0, sale_id uuid references sales(id), created_at timestamptz not null default now());
create table if not exists commissions (id uuid primary key default gen_random_uuid(), company_id uuid not null references companies(id) on delete cascade, sale_id uuid references sales(id), seller text, rate numeric(8,3) not null default 0, amount numeric(14,2) not null default 0, status text not null default 'pending', created_at timestamptz not null default now());
create table if not exists audit_logs (id uuid primary key default gen_random_uuid(), company_id uuid not null references companies(id) on delete cascade, user_id uuid, action text not null, entity text not null, entity_id uuid, old_data jsonb, new_data jsonb, created_at timestamptz not null default now());

create or replace function is_company_member(target_company uuid) returns boolean language sql stable security definer set search_path = public as $$ select exists (select 1 from company_users where company_id = target_company and user_id = auth.uid() and active); $$;

do $$ declare table_name text; begin foreach table_name in array array['company_users','customers','products','sales','sale_items','stock_movements','financial_entries','suppliers','purchases','purchase_items','quotes','commissions','audit_logs'] loop execute format('alter table %I enable row level security', table_name); execute format('drop policy if exists company_isolation on %I', table_name); execute format('create policy company_isolation on %I for all using (is_company_member(company_id)) with check (is_company_member(company_id))', table_name); end loop; alter table companies enable row level security; drop policy if exists company_member_select on companies; create policy company_member_select on companies for select using (is_company_member(id)); end $$;
